package com.piano.sequencer

/** Tracks only diagnostic-pad pitches; caller supplies MIDI note actions. */
class DiagnosticNoteInput(private val noteOn: (Int) -> Unit, private val noteOff: (Int) -> Unit) {
    private val held = mutableSetOf<Int>()
    private val touchClicks = mutableSetOf<Int>()

    fun touchDown(note: Int) {
        if (held.add(note)) noteOn(note)
    }

    fun touchUp(note: Int) {
        release(note)
        touchClicks.add(note)
    }

    fun touchCancel(note: Int) = release(note)

    /** Return true when this click was generated by touch and already handled. */
    fun click(note: Int): Boolean {
        if (touchClicks.remove(note)) return true
        noteOn(note)
        noteOff(note)
        return false
    }

    fun releaseHeld() {
        held.toList().forEach(::release)
    }

    private fun release(note: Int) {
        if (held.remove(note)) noteOff(note)
    }
}
